## Ket qua tim kiem

### 1. SMS_InputVoucherDetail.cs - DA TIM THAY

**Duong dan:** `g:\0.CMS-MAIN-ALL\-vat-tuquangbin\SMSObject\SMS_InputVoucherDetail.cs`

Noi dung day du file (gom phuong thuc `GetListReturnInput`):

```1:75:g:\0.CMS-MAIN-ALL\-vat-tuquangbin\SMSObject\SMS_InputVoucherDetail.cs

#region Using

using System;
using System.Data;
using System.Collections;
using DCore;

#endregion

namespace SMSObject
{
    public partial class SMS_InputVoucherDetail
    {	

		#region Methods	

        public bool DeleteOfInputVoucher()
        {
            if (!bolIsExistIData)
                objIData = DCore.Data.CreateData();
            try
            {
                objIData.CreateNewStoredProcedure("SMS_InputVoucherDetail_DeleteOfInputVoucher");
                objIData.AddParameter(P_InputVoucherID, this.lngInputVoucherID);
                objIData.ExecNonQuery();
                return true;
            }
            catch (Exception objEx)
            {
                if (bolIsExistIData)
                    this.RollBackTransaction();
                new SystemError(SystemConfig.ConnectionString, "Loi xoa thong tin SMS_InputVoucherDetail", objEx);
                this.objErrorException = objEx;
                return false;
            }
            finally
            {
                if (!bolIsExistIData)
                    objIData.Disconnect();
            }
        }

        public DataTable GetList(long? inputVoucherID)
        {
            return GetDataTable("[SMS_InputVoucherDetail_GetList]", "@InputVoucherID",inputVoucherID);
        }

        public DataTable GetListReturnInput(long? inputVoucherID)
        {
            return GetDataTable("[SMS_InputVoucherDetail_ReturnInput]", "@InputVoucherID", inputVoucherID);
        }

		#endregion

	}
}
```

